<script setup lang="ts">
import {computed} from 'vue'
import {GraduationCap,Heart,MessageCircle,BookOpen,FlaskConical} from '@lucide/vue'
import type {Player,RoomState} from '../types'
const props=defineProps<{player:Player;state:RoomState;busy:boolean;now:number}>()
const emit=defineEmits<{act:[action:string,payload:Record<string,unknown>]}>()
const students=computed(()=>props.player.students.filter(s=>!s.graduatedAt)),alumni=computed(()=>props.player.students.filter(s=>s.graduatedAt))
const quota=computed(()=>props.player.benefits.quota)
const candidates=computed(()=>props.player.admissions.candidates?.filter(c=>!c.hired)||[])
const degree=(value:string)=>value==='masters'?'硕士生':'博士生'
function left(at:number){return Math.max(1,Math.ceil((at+4*3600000-props.now)/3600000))+' 小时后可交流'}
</script>
<template>
 <div class="panel-heading"><div><span class="eyebrow">A SMALL GROUP, A LITTLE KINDNESS</span><h1>我的小课题组</h1></div><GraduationCap :size="32"/></div>
 <div class="team-overview"><div><span>第 {{ player.admissions.year }} 学年</span><h2>研究有进度，人也要好好的。</h2><p>{{ state.academicYearDays===0?'每个现实自然年':state.academicYearDays+' 个现实日为一学年' }}更新名额。离线研究照常推进，无强制组会，也不扣连续登录分。</p></div><span><b>{{ students.length }} / {{ quota.capacity }}</b>在组学生</span></div>
 <div class="quota-row"><span>硕士指标 <b>{{ player.admissions.masters }} / {{ quota.masters }}</b></span><span>博士指标 <b>{{ player.admissions.phds }} / {{ quota.phds }}</b></span><span>累计毕业 <b>{{ player.graduates }} 位</b></span></div>
 <div v-if="!students.length" class="empty-state"><BookOpen :size="30"/><p>课题组还很安静。<br/>招一位同学，一起研究一点小问题。</p></div>
 <div class="student-grid"><article v-for="s in students" :key="s.id" class="student-card"><div class="student-heading"><span class="student-avatar">{{ s.name.slice(-1) }}</span><div><h2>{{ s.name }} <small>{{ degree(s.degree) }}</small></h2><p>{{ s.topic }}</p></div><span class="state-pill">{{ s.trait }}</span></div><div class="student-meters"><label>科研进度 <b>{{ s.progress }} / {{ s.target }}</b><div class="progress-track"><i :style="{width:Math.min(100,s.progress/s.target*100)+'%'}"/></div></label><label><Heart :size="14"/>最近心情 <b>{{ s.wellbeing }} / 100</b><div class="progress-track wellbeing" :class="{low:s.wellbeing<45}"><i :style="{width:s.wellbeing+'%'}"/></div></label></div><p class="muted">每 6 小时收到一轮研究反馈，最多保存 4 轮；{{ s.degree==='masters'?'学生 +6、自身论文 +2':'学生 +5、自身论文 +3' }} 进度。心情低于 45 时，先缓一缓。</p><div class="care-actions"><button :disabled="busy||!!s.lastCareAt&&now<s.lastCareAt+4*3600000" @click="emit('act','student_care',{id:s.id,mode:'guide'})"><BookOpen :size="15"/>聊聊研究<small>进度 +10 · 心情 +3</small></button><button :disabled="busy||!!s.lastCareAt&&now<s.lastCareAt+4*3600000" @click="emit('act','student_care',{id:s.id,mode:'listen'})"><MessageCircle :size="15"/>听听近况<small>进度 +3 · 心情 +15</small></button><button :disabled="busy||player.funds<20||!!s.lastCareAt&&now<s.lastCareAt+4*3600000" @click="emit('act','student_care',{id:s.id,mode:'sprint'})"><FlaskConical :size="15"/>一起做实验<small>进度 +16 · 心情 −12 · 20 经费</small></button></div><p v-if="s.lastCareAt&&now<s.lastCareAt+4*3600000" class="muted">{{ left(s.lastCareAt) }}，也给同学一点消化的时间。</p><button v-if="s.progress>=s.target" class="primary wide" :disabled="busy||s.wellbeing<40" @click="emit('act','student_graduate',{id:s.id})">准备毕业啦 · {{ s.wellbeing<40?'先关心一下近况':s.degree==='masters'?'+120 经费、2 声望、8 论文进度':'+200 经费、4 声望、15 论文进度' }}</button></article></div>
 <div class="section-title"><h2>本学年招生小册</h2><span>不抢名额，按自己的节奏</span></div><div class="candidate-grid"><article v-for="c in candidates" :key="c.id"><span class="small-label">{{ degree(c.degree) }}申请</span><h3>{{ c.name }}</h3><p>{{ c.topic }}</p><small>{{ c.trait }}</small><button class="secondary wide" :disabled="busy||students.length>=quota.capacity||player.admissions[c.degree]>=quota[c.degree]||player.funds<(c.degree==='masters'?100:160)" @click="emit('act','student_hire',{id:c.id})">欢迎入组 · {{ c.degree==='masters'?100:160 }} 经费</button></article></div>
 <div v-if="alumni.length" class="alumni"><GraduationCap :size="18"/><span>从这里出发的同学：{{ alumni.map(s=>s.name).join('、') }}。每位毕业生让项目经费长期 +1%。</span></div><p class="gentle-footer">这是轻量培养玩法。学生的心情只是游戏数值，关怀不会成为新的打卡任务。</p>
</template>
